  public double DROP_AFTER_S { get; set; }
  public string LAST_UPDATE_EPOCH { get; set; }
  public List<TMSIdentifierT> IDENTIFIERS { get; set; }
  public TMSProvenanceT SOURCE { get; set; }

  public TMST() {
    this.ID = null;
    this.TRACK_ID = null;
    this.ENVIRONMENT = trackEnvironment.UNKNOWN;
    this.EPOCH = null;
    this.LATITUDE = 0.0;
    this.LONGITUDE = 0.0;
    this.ALTITUDE_M = 0.0;
    this.GROUND_SPEED_MPS = 0.0;
    this.VELOCITY_NORTH_MPS = 0.0;
