    this.TURN_RATE_DPS = 0.0;
    this.VERTICAL_RATE_MPS = 0.0;
    this.MODEL_ID = null;
    this.MODEL_PARAMETERS = null;
    this.PROPAGATION_VALID_UNTIL = null;
    this.POSITION_UNCERTAINTY_M = 0.0;
    this.INNOVATION_GATE_SIGMA = 0.0;
    this.INNOVATION_GATE_DISTANCE_M = 0.0;
    this.TOLERANCE_M = 0.0;
    this.TRACK_STATUS = TrkTrackStatus.ACTIVE;
    this.STALE_AFTER_S = 0.0;
