      && verifier.VerifyString(tablePos, 6 /*TRACK_ID*/, false)
      && verifier.VerifyField(tablePos, 8 /*ENVIRONMENT*/, 1 /*trackEnvironment*/, 1, false)
      && verifier.VerifyString(tablePos, 10 /*EPOCH*/, true)
      && verifier.VerifyField(tablePos, 12 /*LATITUDE*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 14 /*LONGITUDE*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 16 /*ALTITUDE_M*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 18 /*GROUND_SPEED_MPS*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 20 /*VELOCITY_NORTH_MPS*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 22 /*VELOCITY_EAST_MPS*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 24 /*VELOCITY_UP_MPS*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 26 /*HEADING_DEG*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 28 /*COURSE_DEG*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 30 /*TURN_RATE_DPS*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 32 /*VERTICAL_RATE_MPS*/, 8 /*double*/, 8, false)
      && verifier.VerifyString(tablePos, 34 /*MODEL_ID*/, true)
      && verifier.VerifyVectorOfTables(tablePos, 36 /*MODEL_PARAMETERS*/, TMSModelParameterVerify.Verify, false)
      && verifier.VerifyString(tablePos, 38 /*PROPAGATION_VALID_UNTIL*/, false)
      && verifier.VerifyField(tablePos, 40 /*POSITION_UNCERTAINTY_M*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 42 /*INNOVATION_GATE_SIGMA*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 44 /*INNOVATION_GATE_DISTANCE_M*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 46 /*TOLERANCE_M*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 48 /*TRACK_STATUS*/, 1 /*TrkTrackStatus*/, 1, false)
      && verifier.VerifyField(tablePos, 50 /*STALE_AFTER_S*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 52 /*DROP_AFTER_S*/, 8 /*double*/, 8, false)
      && verifier.VerifyString(tablePos, 54 /*LAST_UPDATE_EPOCH*/, false)
      && verifier.VerifyVectorOfTables(tablePos, 56 /*IDENTIFIERS*/, TMSIdentifierVerify.Verify, false)
      && verifier.VerifyTable(tablePos, 58 /*SOURCE*/, TMSProvenanceVerify.Verify, true)
